// Purpose: Serial H2D-Kernel-D2H vs pinned double-buffer双流；用nsys证明重叠。
#include "common.cuh"
#include <cmath>
__global__ void transform(const float*x,float*y,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n){float v=x[i];for(int k=0;k<80;++k)v=fmaf(v,1.00001f,.00001f);y[i]=v;}}
int main(){constexpr int chunks=12,n=1<<20;std::size_t bytes=n*sizeof(float);float *h[2],*in[2],*out[2];cudaStream_t s[2];for(int i=0;i<2;++i){CUDA_OK(cudaMallocHost(&h[i],bytes));CUDA_OK(cudaMalloc(&in[i],bytes));CUDA_OK(cudaMalloc(&out[i],bytes));CUDA_OK(cudaStreamCreate(&s[i]));for(int j=0;j<n;++j)h[i][j]=j*.001f;}Timer timer;timer.start();for(int c=0;c<chunks;++c){int q=c&1;CUDA_OK(cudaMemcpy(in[q],h[q],bytes,cudaMemcpyHostToDevice));transform<<<(n+255)/256,256>>>(in[q],out[q],n);CUDA_OK(cudaMemcpy(h[q],out[q],bytes,cudaMemcpyDeviceToHost));}float serial=timer.stop();timer.start();for(int c=0;c<chunks;++c){int q=c&1;if(c>=2)CUDA_OK(cudaStreamSynchronize(s[q]));CUDA_OK(cudaMemcpyAsync(in[q],h[q],bytes,cudaMemcpyHostToDevice,s[q]));transform<<<(n+255)/256,256,0,s[q]>>>(in[q],out[q],n);CUDA_OK(cudaMemcpyAsync(h[q],out[q],bytes,cudaMemcpyDeviceToHost,s[q]));}CUDA_OK(cudaDeviceSynchronize());float overlap=timer.stop();if(!std::isfinite(h[0][n/2]))return 2;std::cout<<"serial_ms="<<serial<<" double_buffer_ms="<<overlap<<" checksum="<<h[0][n/2]<<'\n';for(int i=0;i<2;++i){cudaStreamDestroy(s[i]);cudaFree(out[i]);cudaFree(in[i]);cudaFreeHost(h[i]);}}
